def is_valid_simple_html_tags(s):
    pattern = re.compile(r'(</?)([a-z])>')
    pos = 0
    stack = []
    n = len(s)
    while pos < n:
        m = pattern.match(s, pos)
        if not m:
            return False
        tag_type, letter = m.group(1), m.group(2)
        if tag_type == '<':
            stack.append(letter)
        else:
            if not stack or stack[-1] != letter:
                return False
            stack.pop()
        pos = m.end()
    return len(stack) == 0

def is_valid_luhn_number(s):
    if len(s) < 2 or not s.isdigit():
        return False
    total = 0
    digits = [int(c) for c in s]
    n = len(digits)
    for i in range(n):
        d = digits[n - 1 - i]
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

