def is_valid_isbn10(s):
    s = s.replace('-', '')
    if len(s) != 10:
        return False
    if not s[:9].isdigit():
        return False
    last = s[9]
    if last == 'X':
        last_val = 10
    elif last.isdigit():
        last_val = int(last)
    else:
        return False
    total = 0
    for i in range(9):
        total += int(s[i]) * (10 - i)
    total += last_val * 1
    return total % 11 == 0

def is_valid_isbn13(s):
    s = s.replace('-', '')
    if len(s) != 13 or not s.isdigit():
        return False
    total = 0
    for i, c in enumerate(s):
        weight = 1 if i % 2 == 0 else 3
        total += int(c) * weight
    return total % 10 == 0

def is_valid_aba_routing_number(s):
    if len(s) != 9 or not s.isdigit():
        return False
    d = [int(c) for c in s]
    checksum = 3 * (d[0] + d[3] + d[6]) + 7 * (d[1] + d[4] + d[7]) + 1 * (d[2] + d[5] + d[8])
    return checksum % 10 == 0

def is_valid_serial_checksum(s):
    charset = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if len(s) != 8:
        return False
    for c in s:
        if c not in charset:
            return False
    if not s[7].isdigit():
        return False
    total = sum(charset.index(c) for c in s[:7])
    return str(total % 10) == s[7]

