def is_valid_simple_url(s):
    if ' ' in s:
        return False
    if s.startswith('https://'):
        rest = s[len('https://'):]
    elif s.startswith('http://'):
        rest = s[len('http://'):]
    else:
        return False
    if not rest:
        return False
    slash_idx = rest.find('/')
    if slash_idx == -1:
        domain = rest
    else:
        domain = rest[:slash_idx]
    if not domain:
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label:
            return False
        if label.startswith('-') or label.endswith('-'):
            return False
        for c in label:
            if not (c.isalnum() or c == '-'):
                return False
    tld = labels[-1]
    if not tld.isalpha() or len(tld) < 2:
        return False
    return True

