def is_valid_query_string(s):
    if not s.startswith('?'):
        return False
    rest = s[1:]
    if not rest:
        return False
    pairs = rest.split('&')
    for pair in pairs:
        if pair.count('=') != 1:
            return False
        key, value = pair.split('=')
        if not key or not value:
            return False
        if not key.isalnum() or not value.isalnum():
            return False
    return True
